        key_items = {  },
        warnings = {  },
      },
      {
        order = 27,
        marker = "*",
        depth = 1,
        instruction = "Level 78 Fishing is required in order to get the Serpent Rumors key item, so that is the absolute minimum level required to begin this quest; however, fishers lower than level 90 fishing will have a very difficult time reeling in the fish necessary for the quest. Close to level 100 fishing is highly recommended.",
