        warnings = {  },
      },
      {
        order = 28,
        marker = "*",
        depth = 1,
        instruction = "You will break your rod a lot trying to catch these fish, so consider either raising woodworking or bringing a woodworking mule along for repairs. Woodworking skill level of 68+ can repair a Broken Lu Shang's Rod, but you can possibly use up an entire stack of crystals or more per repair. Suggested skill level of 74+ for a better success rate. Please also be... Required details: woodworking, Broken Lu Shang's Rod.",
